package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import org.json.*;import java.io.*;import java.util.*;
final class NarrationIndex {
 static List<WavCues.Cue> cues(NarrationJob job){List<WavCues.Cue> list=new ArrayList<>();JSONArray arr=job.data.optJSONArray("cues");if(arr!=null)for(int i=0;i<Math.min(WavCues.MAX,arr.length());i++){JSONObject c=arr.optJSONObject(i);if(c!=null)list.add(new WavCues.Cue(c.optLong("ms"),c.optString("label"),c.optInt("part")));}return list;}
 static void checkpoint(NarrationJob job,int part,int offset,int end,String text,SpeechLayout.Plan plan,long milliseconds)throws JSONException{JSONArray values=job.data.optJSONArray("cues");if(values==null)values=new JSONArray();if(values.length()>=WavCues.MAX)return;String label=offset==0||values.length()==0?job.s("chapter"):"";if(plan!=null&&plan.pauseAfter(end)>0)for(SpeechLayout.Title t:plan.titles)if(t.start>=offset&&t.end==end){label=text.substring(t.start,t.end);break;}if(!label.isEmpty()){boolean duplicate=false;for(int i=Math.max(0,values.length()-2);i<values.length();i++){JSONObject c=values.getJSONObject(i);if(c.optLong("ms")==milliseconds&&c.optString("label").equals(label))duplicate=true;}if(!duplicate)values.put(new JSONObject().put("ms",milliseconds).put("label",AudioTitles.limit(label,128,512)).put("part",part));}job.put("cues",values);}
 static void register(Context c,Uri target,String book,String title,long duration,List<WavCues.Cue> cues){try(PlusStore db=new PlusStore(c)){android.database.sqlite.SQLiteDatabase sql=db.getWritableDatabase();sql.beginTransaction();try{List<StudyStore.Row> old=db.rows("audio_tracks","uri=?",new String[]{target.toString()},null,1);long id;if(old.isEmpty())id=db.save("audio_tracks",StudyStore.values("uri",target.toString(),"book_uri",book,"title",title,"duration",duration,"created",System.currentTimeMillis()));else{id=old.get(0).id();sql.update("audio_tracks",StudyStore.values("duration",duration,"title",title),"id=?",new String[]{""+id});sql.delete("audio_cues","track=?",new String[]{""+id});}for(WavCues.Cue cue:cues)db.save("audio_cues",StudyStore.values("track",id,"position",cue.milliseconds,"label",cue.label,"segment",cue.segment));sql.setTransactionSuccessful();}finally{sql.endTransaction();}}catch(Exception e){AppDiagnostics.record(c,"narration-index",e);}}
 static List<WavCues.Cue> load(Context c,Uri uri)throws Exception{try(PlusStore db=new PlusStore(c)){List<StudyStore.Row> tracks=db.rows("audio_tracks","uri=?",new String[]{uri.toString()},null,1);if(!tracks.isEmpty()){List<WavCues.Cue> out=new ArrayList<>();for(StudyStore.Row row:db.rows("audio_cues","track=?",new String[]{""+tracks.get(0).id()},"position",WavCues.MAX))out.add(new WavCues.Cue(row.n("position"),row.s("label"),(int)row.n("segment")));if(!out.isEmpty())return out;}}try(InputStream in=c.getContentResolver().openInputStream(uri)){if(in==null)return Collections.emptyList();return WavCues.read(in);}}
 static void show(MediaActivity a){PlusUi.run(a,()->{List<WavCues.Cue> cues=load(a,a.uri);PlusUi.post(a,()->{if(cues.isEmpty()){PlusUi.toast(a,"Este áudio não tem índice de capítulos.");return;}String[] names=new String[cues.size()];for(int i=0;i<names.length;i++)names[i]=ReaderActivity.clock((int)Math.min(Integer.MAX_VALUE,cues.get(i).milliseconds))+" · "+cues.get(i).label;new UiDialog.Builder(a).setTitle("Capítulos e títulos").setItems(names,(d,n)->{if(a.service!=null)a.service.seek(cues.get(n).milliseconds);}).setNegativeButton("Fechar",null).show();});});}
 static void library(ReaderActivity a){PlusUi.run(a,()->{List<StudyStore.Row> rows;try(PlusStore db=new PlusStore(a)){rows=db.rows("audio_tracks","book_uri=?",new String[]{a.uri.toString()},"created DESC",500);}PlusUi.post(a,()->{if(rows.isEmpty()){PlusUi.toast(a,"Ainda não há narrações guardadas deste livro.");return;}String[] names=new String[rows.size()];for(int i=0;i<names.length;i++)names[i]=rows.get(i).s("title");new UiDialog.Builder(a).setTitle("Narrações guardadas").setItems(names,(d,n)->a.startActivity(new Intent(a,MediaActivity.class).setDataAndType(Uri.parse(rows.get(n).s("uri")),"audio/wav").putExtra("name",rows.get(n).s("title")))).setNegativeButton("Fechar",null).show();});});}
 static void sleep(MediaActivity a){PlusUi.run(a,()->{List<WavCues.Cue> cues=load(a,a.uri);long position=a.service==null?0:a.service.position(),end=a.service==null?0:a.service.duration();for(WavCues.Cue cue:cues)if(cue.milliseconds>position+500){end=cue.milliseconds;break;}final long target=end;PlusUi.post(a,()->SleepTimer.show(a,a.uri.toString(),0,target));});}
 private NarrationIndex(){}
}
